public enum TransactionType {
    INCOME,
    EXPENSE
}

public final class Transaction {
    private final Account account;
    private final TransactionType type;
    private final Money amount;

    public Transaction(Account account, TransactionType type, Money amount) {
        if (account == null) {
            throw new IllegalArgumentException("account is required");
        }
        if (type == null) {
            throw new IllegalArgumentException("transaction type is required");
        }
        if (amount == null) {
            throw new IllegalArgumentException("amount is required");
        }
        if (amount.amount().signum() <= 0) {
            throw new IllegalArgumentException("transaction amount must be positive");
        }
        this.account = account;
        this.type = type;
        this.amount = amount;
    }

    public Account account() { return account; }
    public TransactionType type() { return type; }
    public Money amount() { return amount; }
}

public enum TransactionType {
    INCOME(1),
    EXPENSE(-1);

    private final int signedEffect;

    TransactionType(int signedEffect) {
        this.signedEffect = signedEffect;
    }

    public int signedEffect() {
        return signedEffect;
    }
}

